    <p>Fire needs heat, fuel and oxygen. Causes in a work environment include flammable substances, electrical faults, combustible materials, naked flames, smoking and sparks. Fires are prevented by safe storage, correct electrical use, cleanliness, attending to flames, obeying signs, smoke detectors, serviced extinguishers and drills.</p>
