    <div style="background:#3e2723;padding:20px;border-radius:12px;border:1px solid #ffb74d;margin-bottom:20px;">
    <h3 style="color:#fff3e0;margin-top:0;">🧠 Lesson Summary</h3>
    <p>Fires are fought by cooling (removing heat), smothering (cutting off oxygen), starving (removing fuel) and interrupting (breaking the chain reaction). Extinguishers are used with PASS. In a fire, raise the alarm, fight only small fires safely, never use water on electrical or oil fires, leave calmly and go to the assembly point.</p>
    <h4 style="color:#fff3e0;margin:16px 0 6px 0;">🗒️ Revision notes</h4>
    <ul style="margin:6px 0;padding-left:22px;">
    <li>Four techniques.</li>
    <li>PASS.</li>
    <li>Fire response.</li>
    </ul>
    </div>
